import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.Base64;import java.util.prefs.Preferences;import javax.crypto.Cipher;import javax.crypto.KeyGenerator;import javax.crypto.SecretKey;import javax.crypto.spec.GCMParameterSpec;
public final class SecurityUtil {private static final String TRANSFORMATION="AES/GCM/NoPadding",KEY_NAME="employee-pii-aes256-key";private static final int IV_LENGTH=12,TAG_LENGTH=128;private static final SecureRandom RANDOM=new SecureRandom();private static final Preferences P=Preferences.userNodeForPackage(SecurityUtil.class);private static SecretKey key(){try{String stored=P.get(KEY_NAME,"");if(!stored.isEmpty())return new javax.crypto.spec.SecretKeySpec(Base64.getDecoder().decode(stored),"AES");KeyGenerator generator=KeyGenerator.getInstance("AES");generator.init(256);SecretKey generated=generator.generateKey();P.put(KEY_NAME,Base64.getEncoder().encodeToString(generated.getEncoded()));return generated;}catch(Exception e){throw new IllegalStateException("Unable to initialize employee PII encryption key",e);}}public static String encrypt(String plainText){if(plainText==null||plainText.isEmpty())return plainText;try{byte[] iv=new byte[IV_LENGTH];RANDOM.nextBytes(iv);Cipher cipher=Cipher.getInstance(TRANSFORMATION);cipher.init(Cipher.ENCRYPT_MODE,key(),new GCMParameterSpec(TAG_LENGTH,iv));byte[] payload=cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8)),combined=new byte[iv.length+payload.length];System.arraycopy(iv,0,combined,0,iv.length);System.arraycopy(payload,0,combined,iv.length,payload.length);return Base64.getEncoder().encodeToString(combined);}catch(Exception e){throw new IllegalStateException("Unable to encrypt employee PII",e);}}public static String decrypt(String cipherText){if(cipherText==null||cipherText.isEmpty())return cipherText;try{byte[] combined=Base64.getDecoder().decode(cipherText);if(combined.length<=IV_LENGTH)return cipherText;byte[] iv=java.util.Arrays.copyOfRange(combined,0,IV_LENGTH),payload=java.util.Arrays.copyOfRange(combined,IV_LENGTH,combined.length);Cipher cipher=Cipher.getInstance(TRANSFORMATION);cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(TAG_LENGTH,iv));return new String(cipher.doFinal(payload),StandardCharsets.UTF_8);}catch(Exception ignored){return cipherText;}}private SecurityUtil(){}}
